package com.yeyamo_mobile.api.admin_service.event;
import java.util.*;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.admin_service.service.AuditService;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class AdminAuditEventConsumer{
 private final ObjectMapper mapper;private final AuditService audit;private final AdminProcessedEventRepository processed;public AdminAuditEventConsumer(ObjectMapper m,AuditService a,AdminProcessedEventRepository p){mapper=m;audit=a;processed=p;}
 @KafkaListener(topics="${yeyamo.kafka.topics.admin-audit-events:admin.audit.events}",groupId="${spring.kafka.consumer.group-id:admin-service}-audit")@Transactional public void consume(String raw)throws Exception{JsonNode e=mapper.readTree(raw);UUID eventId=UUID.fromString(required(e,"eventId"));if(processed.existsById(eventId))return;JsonNode p=e.path("payload");Map<String,Object>metadata=p.has("metadata")?mapper.convertValue(p.path("metadata"),new TypeReference<>(){}):Map.of();audit.recordExternal(required(p,"actorId"),text(p,"actorRole"),required(p,"action"),required(p,"targetType"),text(p,"targetId"),required(p,"service"),text(e,"correlationId"),metadata);processed.save(new AdminProcessedEvent(eventId,"AdminAuditEvent"));}
 private String required(JsonNode n,String f){String v=text(n,f);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}
}
